preConditionHook:
// Highest(h, breakoutLookback)[4]: the window of bars 4 .. breakoutLookback+3,
// i.e. the bars before the breakout bar at offset 3. EL's Extremes() seeds at
// the first bar of the window and scans the rest with a strict,
// tolerance-carrying comparison (see CloseAbovePriorHighestHigh).
priorHighestHigh = high[4];
priorLowestLow = low[4];
for (int i = 5; i <= (int)breakoutLookback + 3; ++i) {
    if (el_gt(high[i], priorHighestHigh)) priorHighestHigh = high[i];
    if (el_lt(low[i], priorLowestLow)) priorLowestLow = low[i];
}
